                let firstTokenAt = null;
                let trace = null;
                let answer = '';
                let sources = [];
                let payloadLength = 0;
                let payloadChars = 0;
                let failure = '';

                try {
                    this.askStatus = 'Thinking…';
                    const recentSourceIds = askSourceIdsInRecent(loadAskSession(), 18);
                    // Keep all regular site context, then add fragment chunks retrieved for this question.
                    const contexts = diversifyAskWritingContexts(
                        await allAskContexts(question),
                        question,
                        telemetry.event_id,
                        recentSourceIds,
