                if (!message || this.viewBusy) return;
                // Site-wide lock: only one View may compose at a time across
                // the homepage, the palette, and the /views composer.
                if (isViewComposing()) {
                    window.dispatchEvent(new CustomEvent('open-site-view'));
                    return;
                }
                const seq = ++this._viewSeq;
                if (this._viewAbortController) this._viewAbortController.abort();
                const controller = new AbortController();
                this._viewAbortController = controller;
                this.viewError = '';
                this.askError = '';
                this.viewBusy = true;
                this.viewStartedAt = Date.now();
                beginViewCompose('home', this.viewStartedAt, message);
                try {
                    if (isDevelopMode(rawMessage)) {
                        const fakeJob = {
                            version: 1,
                            jobId: `develop-${Date.now()}-${seq}`,
                            status: 'composing',
                            message: DEVELOP_VIEW_LABEL,
                            surface: 'home',
                            originRoute: '/home',
                            startedAt: Date.now(),
                        };
                        window.dispatchEvent(new CustomEvent('site-view-job', { detail: fakeJob }));
                        await developViewDelay(controller.signal);
                        if (controller.signal.aborted || seq !== this._viewSeq) {
                            throw new DOMException('Aborted', 'AbortError');
                        }
