.home-ask-panel {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  box-sizing: border-box;
  /* The Ask conversation moves up as a whole so the input bar's bottom line
     lands on the hero's PwC row bottom, which stays where it is. */
  padding: clamp(28px, 4vh, 44px) clamp(26px, 3vw, 42px) calc(clamp(24px, 4.2vh, 44px) - 1px);
  border: 1px solid var(--home-hairline);
  border-left: 0;
  background: rgba(255, 255, 255, 0.28);
}
.home-ask-focus {
  position: absolute;
  z-index: 3;
  /* The first Current Focus title shares the cap line of the Henry H: the hero
     copy's top padding plus the display type's ink offset (≈0.13em of the h1),
     minus the small label's own ink offset. */
  top: calc(clamp(30px, 4.5vh, 54px) + 0.13 * clamp(3.3rem, 5.1vw, 5.5rem) - 5.7px);
  right: clamp(26px, 3vw, 42px);
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.52rem;
  pointer-events: auto;
  transform: translateY(0) scale(1);
