  padding-left: 1.25rem;
  color: #6a6a70;
  text-align: right;
  text-decoration: none;
  transition:
    color 240ms cubic-bezier(0.22, 1, 0.36, 1),
    transform 240ms cubic-bezier(0.22, 1, 0.36, 1),
    opacity 240ms ease;
