  font-size: 0.68rem;
  line-height: 1.3;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}
.home-ask-focus-arrow {
  position: absolute;
  left: 0;
  top: 50%;
  width: 0.82rem;
  height: 0.82rem;
  opacity: 0;
  transform: translateY(-50%) translateX(-4px);
  transition:
    opacity 220ms ease,
    transform 240ms cubic-bezier(0.22, 1, 0.36, 1);
