.home-ask-panel.is-engaged .home-ask-focus {
  opacity: 0;
  transform: translateY(-48px) scale(0.965);
  visibility: hidden;
  pointer-events: none;
  transition:
    opacity 260ms ease-out,
    transform 440ms cubic-bezier(0.22, 1, 0.36, 1),
    visibility 0s linear 440ms;
}
.home-ask-focus-return {
  position: absolute;
  z-index: 4;
  /* Sits on the same horizontal line as the "Ask the site" eyebrow: roughly
     half the height difference between the small label and the button. */
  top: calc(clamp(28px, 4vh, 44px) - 0.65px);
  right: clamp(26px, 3vw, 42px);
  display: inline-flex;
  align-items: center;
  gap: 0.42rem;
  padding: 0;
  border: 0;
  background: transparent;
  color: #77777d;
  font-family: "Quattrocento Sans", sans-serif;
  font-size: 0.62rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  line-height: 1;
  text-transform: uppercase;
  cursor: pointer;
  opacity: 0;
  transform: translateY(-6px) scale(0.96);
  visibility: hidden;
  pointer-events: none;
  transition:
    opacity 280ms ease 180ms,
    transform 360ms cubic-bezier(0.22, 1, 0.36, 1) 180ms,
    visibility 0s linear 640ms;
}
.home-ask-focus-return i {
  font-size: 0.72rem;
  line-height: 1;
  transition: transform 220ms cubic-bezier(0.22, 1, 0.36, 1);
}
.home-ask-panel.is-engaged .home-ask-focus-return {
  opacity: 1;
  transform: translateY(0) scale(1);
